#!/usr/bin/env python3
"""
Comprehensive Org-mode to HTML Slides Converter
Converts .org files with full org syntax support to professional HTML slides.
"""

import re
import sys
import os
import json

def parse_org_content(content):
    """Parse org content into structured slide objects."""

    slides = []
    current_slide = None
    current_subslide = None
    in_source_block = False
    in_source_code = False
    source_lang = ""
    source_body = ""
    source_header = ""

    lines = content.split('\n')

    for line_num_idx, line in enumerate(lines, start=1):
        # Check for source code block start
        raw_line = line
        clean_line = line.rstrip()  # Strip trailing whitespace

        # Handle source block markers (#+begin_src and end_src)
        if clean_line.startswith('#+begin_src'):
            # This is a header marker, content goes into next lines
            in_source_block = True
            in_source_code = True
            source_lang = clean_line.replace('#+begin_src', '').strip()
            source_header = clean_line[15:].strip()
            continue
        elif clean_line.startswith('#+end_src'):
            if in_source_block:
                # Add the source block content if we have any
                if source_body:
                    if current_slide:
                        # Check if this should be part of slide or next slide
                        # For now, we'll keep it with current slide
                        slide_id = clean(source_header) if clean(source_header) else source_lang or f'source-{len(slides)}'
                        source_markdown = convert_source_to_markdown(source_body, source_lang)
                        if source_markdown.strip():
                            current_slide['markdown_content'].append(source_markdown)
                        else:
                            current_slide['markdown_content'].source_block = True
                else:
                    # Empty source block, don't add content
                    pass

                # Reset flags
                in_source_block = False
                in_source_code = False
                source_body = ""
                continue

        # Skip header lines (#+)
        if clean_line.startswith('#+'):
            continue

        # Skip comment block start (#+BEGIN_COMMENT)
        if clean_line.startswith('#+BEGIN_COMMENT') or clean_line.startswith('#+END_COMMENT'):
            continue
        if clean_line.startswith('#+BEGIN_EXAMPLE'):
            in_source_block = True
            in_source_code = True
            source_lang = 'example'
            continue
        if clean_line.startswith('#+END_EXAMPLE'):
            if in_source_code:
                if source_body:
                    slide_id = source_lang or 'example'
                    markdown = convert_source_to_markdown(source_body, 'example')
                    if current_slide and markdown.strip():
                        current_slide['markdown_content'].source_block.append(markdown)
                in_source_code = False
                source_body = ""
            continue

        # Skip empty lines unless we're in a block
        if not clean_line.strip():
            if not in_source_code:
                continue

        # Track if this line looks like list content
        is_list_item = False
        has_marker = clean_line.strip().startswith('-*') or clean_line.strip().startswith('*') or ' - [' in clean_line or '*' in clean_line or '[-' in clean_line
        if has_marker:
            is_list_item = True

        # Check for slide header (level-1 headline)
        if clean_line.startswith('*') and not clean_line.startswith('**') and not clean_line.startswith('*#') and clean_line.count('*') == 1:
            # Start of a new slide
            if current_slide:
                # Save current slide
                if current_slide.get('markdown_content') or current_slide.get('source_blocks'):
                    slides.append(current_slide)

            # Create new slide
            # Remove the asterisk marker
            heading = clean_line.strip()
            clean_heading = re.sub(r'^\*', '', heading).strip()

            # Handle :: format for slides
            if '::' in clean_heading:
                match = re.search(r'^([^:]+)::([^:]+)$', clean_heading)
                if match:
                    clean_heading = match.group(2).strip()

            slide_id = f'slide-{len(slides)+1}'
            current_slide = {
                'id': f'slide-{len(slides)+1}',
                'heading': heading.rstrip('**').strip(),
                'markdown_content': [],
                'source_blocks': [],
                'is_toc': False,
                'subslides': [],
                'source_info': None
            }
            continue

        # If we're inside a source block
        if in_source_code:
            source_body += (line + '\n') if line else '\n'
            continue

        # Add to current slide
        if current_slide:
            # Skip footnote references (e.g., ^[[fn]]^ or [[footnote:fn]]^)
            if '^' in line:
                continue

            # Convert raw org line to markdown
            markdown = org_line_to_markdown(line)

            if markdown:  # If this line converted to meaningful content
                current_slide['markdown_content'].append(markdown)

        # Handle subslides (level-2 headers)
        elif clean_line.startswith('**') or clean_line.startswith('***'):
            pass  # Handle as subslides within markdown content

        # Handle regular text at list level
        elif clean_line.strip().startswith('- ') or clean_line.strip().startswith('-*'):
            if current_slide:
                current_slide['markdown_content'].append(f"  {organic_to_markdown(clean_line.strip())}")

    # Don't forget the last slide
    if current_slide:
        if current_slide.get('markdown_content') or current_slide.get('source_blocks'):
            slides.append(current_slide)

    return slides

def org_to_markdown(text):
    """Convert raw org line to clean markdown line."""
    text = text.strip()

    # Remove list markers
    text = re.sub(r'^\s*[-*]', '', text)

    # Remove leading asterisks from level markers
    text = re.sub(r'^\*+', '', text)

    # Convert org links to markdown links
    link_pattern = r'\[\[([^|\]]+)\]\[\[([^|\]]*)\]\]'
    text = re.sub(link_pattern, r'<a href="\\1" class="org-link" target="_blank">\\2</a>', text)

    # Remove trailing footnote markers
    text = re.sub(r'\^\s*$', '', text)

    return text

def organic_to_markdown(text):
    """Convert org syntax to markdown syntax."""
    return text

def convert_source_to_markdown(content, lang):
    """Convert source block content to markdown with highlighting."""
    # Simple syntax highlighting (could be improved)
    if lang == 'python':
        highlighted = content.replace('def ', '```python\n').replace('if ', 'if ').replace('for ', 'for ').replace('import ', '# import ')
        return f'```{lang}\n{highlighted.strip()}\n```\n'
    elif lang == 'bash' or lang == 'shell':
        return f'```{lang}\n{content}\n```\n'
    elif lang == 'javascript':
        return f'```{lang}\n{content}\n```\n'
    elif lang == 'python' or lang == '' or lang == None:
        return f'```python\n{content}\n```\n'
    elif lang == 'c++' or lang == 'cpp':
        return f'```cpp\n{content}\n```\n'
    elif lang == 'c#':
        return f'```csharp\n{content}\n```\n'
    elif lang == 'ruby':
        return f'```ruby\n{content}\n```\n'
    else:
        return f'```{lang}\n{content}\n```\n' if lang else '```python\n' + content + '\n```'

