</body>
</html>'''

    return html, len(slides)

def convert_org_file(org_path, html_path=None):
    """Convert org file to HTML slides."""

    if not org_path or not os.path.exists(org_path):
        print(f"[Error] File not found: {org_path}", file=sys.stderr)
        return None

    with open(org_path, 'r', encoding='utf-8') as f:
        org_content = f.read()

    slides = parse_org_content(org_content)

    if not slides:
        print("[Warning] No slides parsed", file=sys.stderr)
        return None

    html, slide_count = generate_html(slides)

    if html_path is None:
        html_path = org_path.replace('.org', '.html')

    with open(html_path, 'w', encoding='utf-8') as f:
        f.write(html)

    return {
        'status': 'success',
        'html_path': html_path,
        'slide_count': slide_count,
        'slides': slides
    }

def convert_org_to_html(org_file='agent_call.org', html_file='agent_call.html'):
    """Main function to convert org to HTML."""

    full_path = os.path.abspath(org_file)

    print(f"[*] Converting: {org_file}")

    result = convert_org_file(full_path, html_file)

    if result and result['status'] == 'success':
        print(f"[✓] Generated: {result['html_path']}")
        print(f"[ℹ]   Total slides: {result['slide_count']}")

    return result

if __name__ == '__main__':
    import argparse

    parser = argparse.ArgumentParser(description='Convert org files to HTML slides.')
    parser.add_argument('org_file', nargs='?', default='agent_call.org', help='Org file to convert')
    parser.add_argument('-o', '--output', nargs='?', help='Output HTML file (default: {org_file}.html)')

    args = parser.parse_args()

    output = args.output or f"{args.org_file}.html"

    result = convert_org_to_html(args.org_file, output)

    if result and result.get('status') == 'success':
        print(f"[✓] Done! Slides: {result['slide_count']}")
    else:
        print(f"[Error] Conversion failed", file=sys.stderr)

#!/usr/bin/env python3
"""
Create HTML slides from Org-mode content - Simplified version
"""

import re
import os

def parse_agent_call_org():
    """Parse agent_call.org into structured data."""

    if not os.path.exists('agent_call.org'):
        print("[Error] agent_call.org not found")
        return {'sections': [], 'footer_items': []}

    with open('agent_call.org', 'r') as f:
        content = f.read()

    sections = []
    current = None

    for line in content.split('\n'):
        stripped = line.rstrip()

        # Skip org special syntax
        if stripped.startswith('#+') or stripped.startswith('#+begin_') or stripped.startswith('#+END_'):
            continue

        # Skip empty lines when not in a block
        if not stripped:
            if current and current.get('content_lines'):
                sections.append(current)
                current = None
            continue

        # Check for header
        header_match = re.match(r'^[*][ ]+(.*)', stripped)
        if header_match:
            header_text = header_match.group(1).strip()
            asterisks = len(header_match.string[0].count('*'))

            # First-level header creates a new slide
            if asterisks == 1:
                # Save current section if it exists
                if current and current.get('content_lines'):
                    sections.append(current)

                section = {
