def parse_agent_call_org():
    """Parse agent_call.org into structured data."""
    if not os.path.exists('agent_call.org'):
        print("[Error] agent_call.org not found")
        return None

    with open('agent_call.org', 'r') as f:
        content = f.read()

    slides = []
    current = None

    for line in content.split('\n'):
        stripped = line.rstrip()

        if not stripped:
            continue

        # Skip org special syntax
        if stripped.startswith('#+') or stripped.startswith('#+BEGIN'):
            continue

        # Header detection
        header_match = re.match(r'^[*][ ]+(.*)', stripped)
        if header_match:
            header_text = header_match.group(1).strip()
            asterisks = len(re.match(r'^[*]+', stripped)) or 1

            # Save current section if exists
            if current and current.get('content_lines'):
                content_str = '\n'.join(current.get('content_lines', ['<em>No content listed</em>']))
                slides.append({
                    'id': f'slide-{len(slides)+1}',
                    'heading': current.get('title', ''),
                    'markdown_content': current.get('content_lines', ['<em>No content listed</em>'])
                })

            # Create new section for first-level header
            if asterisks == 1:
                current = {
                    'title': header_text,
                    'content_lines': [],
                    'id': f'slide-{len(slides)+1}'
                }
            elif asterisks > 1:
                # Subheader
                clean_text = re.sub(r'^[*][ ]+', '', stripped).strip()
                current.setdefault('content_lines', []).append(clean_text)
        elif current:
            clean_text = stripped.strip()
            if clean_text:
                current.setdefault('content_lines', []).append(clean_text)

    # Add final section if exists
    if current and current.get('content_lines'):
        content_str = '\n'.join(current.get('content_lines', ['<em>No content listed</em>']))
        slides.append({
            'id': f'slide-{len(slides)+1}',
            'heading': current.get('title', ''),
            'markdown_content': current.get('content_lines', ['<em>No content listed</em>'])
        })

    return slides

def convert_org_file(org_path, html_path=None):
    """Convert org file to HTML."""
    if not org_path or not os.path.exists(org_path):
        print(f"[Error] File not found: {org_path}", file=__import__('sys').stderr)
        return None

    slides = parse_agent_call_org()
    if not slides:
        print("[Warning] No slides parsed", file=__import__('sys').stderr)
        return None

    html = generate(slides)

    if html_path is None:
        html_path = org_path.replace('.org', '.html')

    with open(html_path, 'w', encoding='utf-8') as f:
        f.write(html)

    return {
        'status': 'success',
        'html_path': html_path,
        'slide_count': len(slides),
        'slides': slides
    }

def main():
    import argparse

    parser = argparse.ArgumentParser(description='Convert org files to HTML slides.')
    parser.add_argument('org_file', nargs='?', default='agent_call.org', help='Org file to convert')
    parser.add_argument('-o', '--output', nargs='?', help='Output HTML file (default: {org_file}.html)')

    args = parser.parse_args()

    output = args.output or f"{args.org_file}.html"

    result = convert_org_file(args.org_file, output)

    if result and result.get('status') == 'success':
        print(f"[✓] Done! Slides: {result['slide_count']}")
    else:
        print(f"[Error] Conversion failed", file=__import__('sys').stderr)

if __name__ == '__main__':
    main()

