@supports not (height:100dvh){:root{--doc-height:calc(100vh - 80px)}}
@media(max-width:768px){.side-panel{position:fixed;width:100%;top:auto;bottom:60px;--doc-height:200px;opacity:0;transform:translateX(100%)}
.side-panel.open{opacity:1;transform:translateX(0)}
.slide-footer{padding-top:1rem;gap:.5rem}.side-panel-toggle{position:fixed;bottom:20px;right:20px;width:44px;height:44px;border-radius:50%;background:#ff3002;color:#fff;font-size:20px;border:none;cursor:pointer;box-shadow:0 2px 8px rgba(255,48,2,0.3);z-index:1000}
@media(max-width:768px) .side-panel{z-index:1000}}'''

    js = r'''const slides = [' + json.dumps([{
        'id': s['id'],
        'heading': s['heading']
    } for s in slides]) + '];
let current = 0;
function showSlide(i) {
    current = i;
    if(i >= slides.length) i = 0;
    if(i < 0) i = slides.length - 1;
    window.scrollTo(0,0);
}
function togglePanel() {
    document.getElementById('side-panel').classList.toggle('open');
}'''

    # Escape special chars
    for s in slides:
        h = re.sub(r'[&<>"\x27]', lambda m: {'&':'&amp;','<':'&lt;','>':'&gt;','"': '&quot;','\'': '&rsquo;'}[m.group()], s['heading'])
        c = '\n'.join(re.sub(r'[&<>"\x27]', lambda m: {'&':'&amp;','<':'&lt;','>':'&gt;','"': '&quo;','\''': '&rsquo;'}[m.group()]), l) for l in s.get('content', []))

    # Build HTML
    lines = []
    lines.append('<!DOCTYPE html>')
    lines.append('<html lang="en">')
    lines.append('<head>')
    lines.append(f'<meta charset="UTF-8">')
    lines.append(f'<title>{slides[0]["heading"][:50]} Slides</title>')
    lines.append(f'<style>{css}</style>')
    lines.append(f'<script>const panel = document.getElementById("side-panel");const toggle = document.getElementById("side-panel-toggle");if(toggle) toggle.onclick=togglePanel;{js}</script>')
    lines.append('</head>')
    lines.append('<body>')

    for i, s in enumerate(slides):
        lines.append(f'<div id="{s["id"]}" class="slide"><h2>{h}</h2><div class="slide-content"><p>{c}</p>')
        lines.append('</div><div class="slide-footer")
        lines.append(f'<a href="#prev"' + ' onclick="showSlide({i-1})">Previous</a>')
        lines.append(f'<a href="#next"' + ' onclick="showSlide({i+1})">Next</a>')
        lines.append(f'<a href="#top"' + '>Top</a>')
        lines.append(f'</div></div>' + '\n')

    # Navigation sidebar
    lines.append('</body>')
    lines.append(f'<div id="side-panel" class="side-panel"><div class="side-panel-header">Contents</div><div class="side-panel-content">')
    lines.append('<ul>')
    for s in slides:
        lines.append(f'    <li><a href="#{s["id"]}">{s["heading"][:50]}</a></li>')
    lines.append('</ul>')
    lines.append('<button id="side-panel-toggle" class="side-panel-toggle" aria-label="Show navigation">&#9777;</button>')
    lines.append('</div>')
    lines.append('')
    lines.append('</html>')
    lines.append('')

    return '\n'.join(lines)

def main():
    org_file = os.path.abspath('agent_call.org')
    html_file = os.path.abspath('agent_slides.html')

    if not os.path.exists(org_file):
        print(f'[Error] {org_file} not found')
        sys.exit(1)

    slides = parse_org_to_slides(org_file)
    if not slides:
        print('[Error] No slides found')
        sys.exit(1)

    html = generate_html(slides)

    try:
        with open(html_file, 'w', encoding='utf-8') as f:
            f.write(html)

        print(f'[OK] Converted {len(slides)} slides to {html_file}')
    except Exception as e:
        print(f'[Error] Failed to write: {e}', file=sys.stderr)
        sys.exit(1)

if __name__ == '__main__':
    main()
